import { GoArray } from "@gotots/runtime/array.js";
export class MemStats {
    Alloc = 0n;
    TotalAlloc = 0n;
    Sys = 0n;
    Lookups = 0n;
    Mallocs = 0n;
    Frees = 0n;
    HeapAlloc = 0n;
    HeapSys = 0n;
    HeapIdle = 0n;
    HeapInuse = 0n;
    HeapReleased = 0n;
    HeapObjects = 0n;
    StackInuse = 0n;
    StackSys = 0n;
    MSpanInuse = 0n;
    MSpanSys = 0n;
    MCacheInuse = 0n;
    MCacheSys = 0n;
    BuckHashSys = 0n;
    GCSys = 0n;
    OtherSys = 0n;
    NextGC = 0n;
    LastGC = 0n;
    PauseTotalNs = 0n;
    PauseNs = GoArray.zero(256, 0n);
    PauseEnd = GoArray.zero(256, 0n);
    NumGC = 0;
    NumForcedGC = 0;
    GCCPUFraction = 0;
    EnableGC = false;
    DebugGC = false;
    BySize = zeroBySize();
}
export function populateMemStats(target, source) {
    target.Alloc = source.heapUsed;
    target.TotalAlloc = source.heapTotal;
    target.Sys = source.rss + source.external + source.arrayBuffers;
    target.HeapAlloc = source.heapUsed;
    target.HeapSys = source.heapTotal;
    target.HeapIdle = source.heapTotal > source.heapUsed
        ? source.heapTotal - source.heapUsed
        : 0n;
    target.HeapInuse = source.heapUsed;
    target.MSpanInuse = source.malloced;
    target.MSpanSys = source.malloced;
    target.OtherSys = source.external + source.arrayBuffers;
    target.NextGC = source.heapLimit;
    target.EnableGC = true;
}
function zeroBySize() {
    const indexes = [];
    const values = [];
    for (let index = 0; index < 61; index += 1) {
        indexes.push(index);
        values.push({ Size: 0, Mallocs: 0n, Frees: 0n });
    }
    return GoArray.literal(61, { Size: 0, Mallocs: 0n, Frees: 0n }, indexes, values);
}
